#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <algorithm>
using namespace std;

int getLimit(int maxN) {
    // 计算埃拉托斯特尼筛所需的安全上界
    long long k = 2LL * maxN + 2;

    if (k < 6) {
        return 20;
    }

    double limit = k * (log((double)k) + log(log((double)k)));
    return (int)limit + 20;
}

vector<char> buildSieve(int limit) {
    // 使用埃拉托斯特尼筛预处理质数
    vector<char> isPrime(limit + 1, true);

    isPrime[0] = false;
    isPrime[1] = false;

    for (int i = 2; 1LL * i * i <= limit; i++) {
        if (isPrime[i]) {
            // 将 i 的所有倍数标记为非质数
            for (int j = i * i; j <= limit; j += i) {
                isPrime[j] = false;
            }
        }
    }

    return isPrime;
}

vector<int> solveCase(const string& s, const vector<char>& isPrime) {
    // 计算当前测试用例中所有被翻转的格子
    vector<int> answer;
    answer.reserve(s.size());

    int cur = 1;

    for (char ch : s) {
        // 字符为 1 时寻找质数格子，否则寻找非质数格子
        bool need = (ch == '1');

        // 第一个目标颜色格子是当前被翻转的位置
        int pos = cur + 1;
        while ((bool)isPrime[pos] != need) {
            pos++;
        }

        answer.push_back(pos);

        // 第二个目标颜色格子是后续人的到达位置
        pos++;
        while ((bool)isPrime[pos] != need) {
            pos++;
        }

        cur = pos;
    }

    return answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;

    vector<string> cases(t);
    int maxN = 0;

    for (int i = 0; i < t; i++) {
        int n;
        cin >> n >> cases[i];

        maxN = max(maxN, n);
    }

    int limit = getLimit(maxN);
    vector<char> isPrime = buildSieve(limit);

    for (const string& s : cases) {
        vector<int> answer = solveCase(s, isPrime);

        cout << answer.size() << '\n';

        for (int i = 0; i < (int)answer.size(); i++) {
            if (i > 0) {
                cout << ' ';
            }

            cout << answer[i];
        }

        cout << '\n';
    }

    return 0;
}
